    getRunLog: {
        parameters: {
            query?: {
                /**
                 * @description Byte offset to read from (EP-8a). Serves the log from this byte to
                 *     the end, for live tailing of a running job: poll with the
                 *     `X-Log-Offset` value the previous response returned and receive only
                 *     what was appended since. Safe because the log file is append-only
                 *     with stable offsets — redaction happens at ingest (T7/S7), before
                 *     the write, so a byte once written is never rewritten.
                 *
                 *     Omitted or `0` returns the whole log, identical to the pre-EP-8a
                 *     response. An offset at or past the end of the file is **not** an
                 *     error: it returns 200 with an empty body and the current
                 *     `X-Log-Offset`, so a client whose bookmark outlived a reaped or
                 *     rotated log can notice and restart from 0 instead of wedging.
                 */
                offset?: number;
            };
            header?: never;
            path: {
                /** @description Backend-minted UUIDv7 trace ID (S11). Opaque to clients. */
                traceId: components["parameters"]["traceId"];
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Log content from `offset` (default 0) to the end of the file. */
            200: {
                headers: {
                    /**
                     * @description Byte offset of the end of the file as measured when this
                     *     response was produced — i.e. where the next poll should resume.
                     *     Measured before the body is written, so it never covers bytes
                     *     the client did not receive.
                     */
                    "X-Log-Offset"?: number;
                    [name: string]: unknown;
                };
                content: {
                    "text/plain": string;
                };
            };
            /**
             * @description Malformed trace id (`invalid_trace_id`). The id becomes a log-file
             *     name, so path separators, `..`, a leading `.`, anything over 64
             *     characters, or any character outside `[A-Za-z0-9._-]` is rejected
             *     before the filesystem is touched (LU-12).
             *
             *     Or a malformed `offset` (`invalid_offset`) — anything that is not a
             *     non-negative integer. Rejected rather than coerced to 0: silently
             *     re-serving the whole file would give a tailing client no signal that
             *     its bookmark was never understood.
             */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            401: components["responses"]["Unauthorized"];
            404: components["responses"]["NotFound"];
            /**
             * @description `log_archive_unavailable` — the run's log was archived to S3 and
             *     its local file is gone, but the archive backend is not configured
             *     (settings blanked after archiving) or the bucket could not be read.
             *     Not a 404: the log exists and the server knows where.
             */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
